module quotations_solver (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [1:0] n,\n    input wire [1:0] a_0,\n    input wire [1:0] a_1,\n    input wire [1:0] a_2,\n    output reg [1:0] max_k,\n    output reg done\n);\n\n    // State declarations with explicit widths\n    localparam [1:0] S_IDLE  = 2'd0;\n    localparam [1:0] S_CHECK = 2'd1;\n    localparam [1:0] S_DONE  = 2'd2;\n    \n    reg [1:0] state;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            max_k <= 2'd0;\n            done <= 1'b0;\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        max_k <= 2'd0;\n                        state <= S_CHECK;\n                    end\n                end\n                \n                S_CHECK: begin\n                    // Evaluate conditions for max_k\n                    if (n == 2'd3 && a_0 >= 2'd2 && a_2 >= 2'd2 && a_1 == 2'd1) begin\n                        max_k <= 2'd2;\n                    end else if (n == 2'd2 && a_0 == 2'd1 && a_1 == 2'd1) begin\n                        max_k <= 2'd1;\n                    end\n                    state <= S_DONE;\n                end\n                \n                S_DONE: begin\n                    done <= 1'b1;\n                    state <= S_IDLE;\n                end\n                \n                default: state <= S_IDLE;\n            endcase\n        end\n    end\nendmodule